'use strict';
const DrillPreview=(()=>{
 function init(d){const $=s=>document.querySelector(s),tabs=$('#drill-preview-tabs'),demo=$('#drill-demo-panel'),records=$('#drill-records-panel'),buttons=[...tabs.querySelectorAll('[data-drill-pane]')];let id=null,pane='demo',recordScroll=0,touch=null;
  function sync(){tabs.hidden=!id;demo.hidden=!!id&&pane==='records';records.hidden=!id||pane!=='records';for(const button of buttons){const selected=button.dataset.drillPane===pane;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1;}d.renderHistory(id,!!id&&pane==='records');}
  function show(next,animate=true){if(!id||!['demo','records'].includes(next)||next===pane)return;if(pane==='records')recordScroll=records.scrollTop;d.stop();d.closeDetails();const direction=next==='records'?1:-1;pane=next;sync();if(next==='records')records.scrollTop=recordScroll;const panel=next==='records'?records:demo;if(animate&&!window.matchMedia('(prefers-reduced-motion:reduce)').matches)panel.animate?.([{opacity:.5,transform:'translateX('+direction*12+'px)'},{opacity:1,transform:'translateX(0)'}],{duration:180,easing:'ease-out'});}
  for(const button of buttons){const action=()=>show(button.dataset.drillPane);if(typeof bindTap==='function')bindTap(button,action);else button.onclick=action;}
  tabs.addEventListener('keydown',event=>{const index=buttons.indexOf(document.activeElement);if(index<0||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;show(buttons[next].dataset.drillPane);buttons[next].focus();});
  for(const surface of [tabs,demo,records]){surface.addEventListener('touchstart',event=>{touch=null;if(!id||event.touches.length!==1||surface===demo&&d.canSwipeDemo?.()===false||event.target.closest('input,textarea,select,button,a,summary'))return;const p=event.touches[0];touch={x:p.clientX,y:p.clientY};},{passive:true});surface.addEventListener('touchend',event=>{const start=touch;touch=null;if(!start||!event.changedTouches.length||window.getSelection?.()?.isCollapsed===false)return;const p=event.changedTouches[0],dx=p.clientX-start.x,dy=p.clientY-start.y;if(Math.abs(dx)>64&&Math.abs(dx)>Math.abs(dy)*1.8)show(dx<0?'records':'demo');},{passive:true});surface.addEventListener('touchcancel',()=>touch=null,{passive:true});}
  return{update(next){if(next!==id){id=next;pane='demo';recordScroll=0;records.scrollTop=0;}sync();},show,reset(){id=null;pane='demo';recordScroll=0;sync();}};
 }
 return{init};
})();
